/// `blocks` is the whole ranking, best first, so its first row is the top that each `relevance` cell is measured
/// against. The search budget measures these lines, so a cap counts what the reader receives. Rendering them in one
/// table keeps michi's cell quoting and truncation as the only definition of a row.
pub fn search_row_texts(blocks: &[RankedBlock], snippet_lines: usize) -> Vec<String> {
    let top_score = blocks.first().map_or(0.0, |top| top.final_score);
    let rows: Vec<Vec<Value>> =
        blocks.iter().map(|block| search_row(block, top_score, snippet_lines).to_vec()).collect();
    let rendered =
        michi::AgentResponse::new("search").items(rows, SEARCH_FIELDS.as_slice()).render(michi::OutputFormat::Text);
    // Rows are the indented lines under the header. michi prints blocks that are not rows (`truncated[N]{..}:` for a
    // cut cell, `totalCount`) at column 0 after them, and those must not count as rows.
    rendered.lines().skip(1).take_while(|line| line.starts_with(' ')).map(str::to_owned).collect()
}

/// Renders a search response as a TOON table of its rows, followed by the truncation count and hints. Each row's
/// `relevance` is a percent of [`SearchResponse::top_score`], so a later page still measures against the first row.
pub fn render_search(response: &SearchResponse, view: &SearchView) -> String {
    let rows: Vec<Vec<Value>> = response
        .results
        .iter()
        .map(|block| search_row(block, response.top_score, view.snippet_lines).to_vec())
        .collect();
    let fields = SEARCH_FIELDS.iter().map(|field| (*field).to_owned()).collect();
    let mut section = michi::Section::toon("search", fields, rows);
    if response.truncated {
        section = section.total_count(Some(response.total_blocks_before_truncation));
    }
    michi::AgentResponse::new("search")
        .section(section)
        .hints(search_hints(response, view))
        .render(michi::OutputFormat::Text)
}

/// What the truncation hint tells a reader to do to see more.
///
/// Rows the caps left out are reached with `--offset`, which names the exact next value so the reader does not pay for
/// the rows already seen; rows the relevance cut dropped, those with a `relevance` below `100 * min_score`, are reached
/// with `--min-score 0`, which keeps the same order, so the same offsets still apply. An offset past the last kept row
/// says so and how many rows there are. The caps are named only when a page came back empty, because an offset would
/// not move past a row that does not fit.
fn truncation_guidance(response: &SearchResponse, view: &SearchView) -> String {

    #[test]
    fn row_texts_hold_one_line_per_block_when_several_cells_are_cut() {
        let ranked = blocks_with_long_signatures(&[1.0, 0.9, 0.8], &[0, 2], 300);
        let texts = search_row_texts(&ranked, DEFAULT_SNIPPET_LINES);
        assert_eq!(texts.len(), ranked.len());
        assert!(texts.iter().all(|text| text.starts_with("  src/f")), "{texts:?}");
    }

    #[test]
    fn the_truncated_block_is_listed_after_the_rows_and_is_not_a_row() {
        let ranked = blocks_with_long_signatures(&[1.0, 0.9], &[1], 250);
        let total = ranked.len();
        let view = SearchView::default();
        let texts = search_row_texts(&ranked, view.snippet_lines);
        assert_eq!(texts.len(), total);
        let response =
            crate::budget::apply_budget(ranked, total, &crate::budget::Budget::default(), &texts, Vec::new());
        assert_eq!((response.results.len(), response.truncated), (2, false));
        let rendered = render_search(&response, &view);
        let tail: Vec<&str> = rendered.lines().skip(1 + total).collect();
        assert_eq!(tail[0], "truncated[1]{row,field,removed}:");
        assert_eq!(tail[1], "  1,symbolSignature,51");
        assert!(texts.iter().all(|text| !tail.contains(&text.as_str())));
    }

    #[test]
    fn relevance_counts_the_rows_only_when_a_cell_is_cut_on_an_offset_page() {
        let ranked = blocks_with_long_signatures(&[1.0, 0.8, 0.6, 0.4], &[2], 250);
        let view = SearchView { min_score: 0.0, ..SearchView::default() };
        let texts = search_row_texts(&ranked, view.snippet_lines);
        assert_eq!(texts.len(), 4);
        let budget = crate::budget::Budget { offset: 2, min_score: 0.0, ..crate::budget::Budget::default() };
        let response = crate::budget::apply_budget(ranked, 4, &budget, &texts, Vec::new());
        let rendered = render_search(&response, &view);
        let lines: Vec<&str> = rendered.lines().collect();
        assert_eq!(lines[0], "search[2]{file,lineStart,lineEnd,nodeKind,parent,symbolSignature,snippet,relevance}:");
        assert_eq!(lines[1], format!("  src/f3.rs,3,4,function,null,{}…,null,60", "x".repeat(199)));
        assert_eq!(lines[2], "  src/f4.rs,4,5,function,null,null,null,40");
        assert_eq!(lines[3], "truncated[1]{row,field,removed}:");
        assert_eq!(lines[4], "  0,symbolSignature,51");
        assert_eq!(lines[5..], ["totalCount: 4", "help[1]: showing 2 of 4; refine with +term/-term"]);
    }

    /// The help line `scores` produce under `budget`, or `None` when the whole result is shown.
    fn help_line(scores: &[f64], budget: &crate::budget::Budget) -> Option<String> {
# 3. One crate with core and agent modules, not two crates

**Status:** Accepted **Date:** 2026-10-23

**Note:** the `core` and `agent` modules are not in place yet. Today `budget.rs`, `cli.rs` and `output/` form the agent layer, behind the `cli` feature; everything else in `lib.rs` is core.

## Context

`08-library-session-api.md` §9.1 splits monokl into `monokl-core` (plumbing: analysis, indices, ranked uncapped results, no serde on result types, no budget) and `monokl-agent` (porcelain: budget, tiktoken, wire types, michi, CLI). The split's purpose is a boundary, not a second artifact: Wisp should depend on core without the CLI layer, and core result types must never become wire types. callisto merged its crates down to four because each crate adds versioning, release and dependency overhead.

## Decision

monokl stays one crate, `crates/monokl`, with the boundary as two top-level modules: `core` for what §9.1 puts in `monokl-core`, and `agent` for what it puts in `monokl-agent`. An architecture test enforces it: `core` never imports from `agent`, never derives `Serialize` on a result type, and never depends on tiktoken or michi. The `agent` module and its dependencies sit behind the `cli` feature, so a library consumer builds core alone.

## Consequences

- One version, one changeset stream, one release; no inter-crate version pins.
- The boundary is a test, not the compiler. A violation fails CI rather than failing to build.
- Wisp depends on `monokl` with default features off, rather than on a separate `monokl-core` crate.
- Existing modules move under `core` or `agent` when that layout lands; until then the architecture test names today's module paths.
- If a real reason appears (a different license, a separate publish, Wisp needing a smaller dependency graph than features allow), the modules become crates along the same line, and a new ADR records it.

## Alternatives considered

- **Two crates now, per §9.1.** The compiler enforces the boundary, at the cost of a second crate to version and release before anything outside monokl consumes core.
# 4. Search stays stateless and every stage has a stated bound

**Status:** Accepted **Date:** 2026-11-10

## Context

Performance problems kept recurring in different forms:

- The tokenizer vocabulary cost 50 ms on every search with a match. A byte estimate replaced it.
- Dedup was quadratic: 30 ms of 51 ms on broad queries. It is now indexed per file.
- The parallel search kept every file's hits past the file ceiling, so memory was unbounded. It now folds ordered, bounded batches.
- The per-file parse thread sizes its stack by input: 8 MiB + 4 KiB per source byte, capped at 1 GiB for TypeScript and 4 GiB for Rust. Very large generated files return nothing, and a failed reservation degrades output by host.
- `ra_ap_syntax` is quadratic in nesting depth. On a 100 KB file, 20k nested parentheses take 1.06 s and 50k take 4.2 s.
- Nothing has a deadline.
- Memory is bounded by file count, not bytes. 40 files of 5 MB reached 213 MB RSS. One 300 MB line reached 736 MB.
- Text search read every file under the directory, including non-source files, and dropped them afterwards. A path-restricted search over 54,009 files (18,171 of them source) took 2,179 ms against rg's 184 ms. A PR that filters by language before reading fixed it.

Each fix was local. The class of problem was not addressed: a stage whose cost depends on an input property nobody bounded.

## Decision

Search stays stateless: no persistent index, no on-disk cache, no daemon, for now.

Every stage states its bound in its doc comment. Work and memory are bounded by output or by bytes, not by input surprises:

1. No thread stack is sized by input. Parse on a fixed-size stack and reject deep nesting with an O(n) pre-scan.
2. Check file size before reading, and cap hit text length.
3. A global `--timeout` stops analysis early and reports what it skipped in a diagnostic.
4. No step is super-linear in match count. A scaling test in CI counts the work (comparisons, reads, filter calls) at two input sizes and asserts the ratio. No test asserts elapsed time: it passes on an idle machine and fails under load.
5. Results are deterministic regardless of thread timing: fold in walk order.
6. A file no analyzer owns is never opened.
7. A search starts threads only for work it has. The parse threads (256 MiB stack each) are started when there is a file to analyze and number `min(CPUs, files to analyze)`: none for no files. A thread count is not looked up before there is work, because asking rayon for it starts its shared pool.

## Consequences

Rule 1 is done. Every parse runs on one 256 MiB stack, and a file whose nesting could pass it is rejected by a linear scan before it is parsed (`TooDeep`). Size is capped by measured parse time and memory (4 MiB), not by the stack.

Rules 2 to 4 are done:

- Rule 2: a file over 4 MiB (the analyzers' parse cap) is checked on its open handle and never read, and is reported as one grouped `over 4 MiB` line. A matching line is kept to 4,096 bytes and the cut lines are counted in a warning. 40 files of 5 MB went from 479 MB to 5 MB of RSS, and one 300 MB line from 752 MB to 5 MB.
- Rule 2, the kept text: text search reads a matching file of at most 256 KiB whole and hands analysis those bytes, so the file is opened once. Extra memory is at most 16 MiB of kept text over all files, however many match, plus 256 KiB for each search thread's file in flight. The budget is charged the capacity of each kept buffer, not its length, and a buffer is read to the size the file had when it was opened and cut to what a shrunk file gave, so a file that changes during the search cannot make kept memory pass it. Text past the budget is dropped and its file opened again by analysis, so the budget changes cost, never output. The 16 MiB is under one analysis thread's bound for a single file (about 150 MB), which stays the bound on peak memory.
- Rule 3: `--timeout <SECONDS>` (default 30, `0` for none) is checked between files in text search and between batches in analysis. Each stage finishes its first batch, and an expired search reports `partial result: ... expired after searching|analyzing N of M files`.
- Rule 4: unit tests next to each stage count work. Dedup (three layouts) and ranking count the pairs compared and assert that 4 times the blocks costs at most 5 (dedup) or 6 (ranking) times as many; a quadratic step costs 16. Text search asserts that the file filter is asked once per file, and a whole search that each matching file is opened once, for text search and analysis together, at two sizes. The failed-lookahead budget of the nesting scan is shown by a scan that only that budget can end.
- Rule 5 is what the ordered batch fold already does.
- Rule 6 holds once the language filter before reading merges (PR 79); until then non-source files are still opened.
- Rule 7 holds for the parse threads, which a search starts once and no wider than its files, and for rayon's shared pool, which text search, ranking and the thread count read touch only when there is something to search or rank. Text search and ranking still use all of that pool for one file: it is shared, started once per process with default stacks, and not sized per search.

The trade-off: a stateless search pays the cold cost on every run, and the bounds reject or skip some inputs (deeply nested or oversized files) that analysis would otherwise attempt. Each skip is reported, not silent.

## Alternatives considered

- **Two-phase search.** Score files cheaply from hit counts and path, then analyze only the top 100. Prototyped and rejected. Across 181 queries on three repos, the top-50 rows changed for 20, including rank 1 (`type`, `default`), and 11 changed inside the top 10. On the TypeScript repository, 4 of 30 queries changed at rank 1. Speedups were 1.25x, 0.88x, 0.91x, 1.04x and 1.7x on the 20,000-file set, because text search and the walk dominate (rg alone takes 364 ms there). A safe stopping bound is not cheap to compute: BM25 statistics and the name bonus depend on the whole analyzed set.
- **On-disk analysis cache keyed by content hash.** It helps only warm repeats, and a fresh checkout is cold. It adds writes, invalidation and read-only sandbox problems. Revisit only if warm repeat latency becomes the measured complaint.
- **Long-lived daemon.** A later step, not needed for current numbers. On main, medians on zod and axios are within a few ms of rg, except zod broad queries at 27.7 ms against 18.4 ms, which print 12 KB against rg's 864 KB.
# 5. Hits and blocks are identified by byte spans, and blocks form a tree

**Status:** Accepted **Date:** 2026-11-11

## Context

A block is a line range plus a copy of its text (`CodeBlock { line_start, line_end, code, .. }`, `types.rs`) and a hit is a whole line (`LineHit { line_number, text }`). Both analyzers hold the exact span when they build a block (`push_block` in `analysis/ts/parse.rs`, `record` in `analysis/rust/parse.rs`) and drop it after cutting lines and `code`. The tree is dropped too: `parent` is a `ParentContext { kind, name }`, not a link to a block.

Later stages re-derive structure from lines or text. Non-test code mentions `line_start`, `line_end`, `matched_lines`, `line_number` or `code` on 87 lines in 11 files. The guessing stages:

- `owned_hits` (`pipeline/mod.rs`) picks a hit's owner by line range, own-text matching, and `outer.code.contains(inner.code)` for equal ranges.
- `snippet` and `signature_shows` (`output/agent.rs`) decide by text whether the signature already shows the first line.
- `encloses_member` and `overlaps_significantly` (`dedup.rs`) compare line ranges, so two disjoint blocks on one line overlap fully.
- `name_match_boost` (`rank/boost.rs`) cuts a signature string at `(`, `<`, `{`, `=`, `:` to recover a name.

The same gap produced 7 fix or test commits in 3 PRs (#66: 3, #68: 1, #77: 3). Ownership was rewritten three times (earliest of equal size, innermost by range, own text on the line) for `} b() {`, `}, // note` and `const a = 1; const needle = 2;`. A test function and its module with the same range were credited twice. A first-line snippet repeated or hid the signature. `pub(crate) fn` was cut to `pub`. `pipeline/proptests.rs` re-implements the old rule as its reference, so it pins the rule, not a contract.

## Decision

We recommend identifying hits and blocks by byte spans and linking blocks into a forest.

- A hit carries its line and the offsets at which its matches start, as ranges of consecutive offsets (a pattern that matches every byte of a line is one range). Where a match ends is not needed: ownership reads the first byte.
- A block carries a byte span and its parent's index in the file's block list, built once by the analyzer.
- The AST supplies `name` and `kind` as typed fields.
- Ownership is per match, in this order. Each match goes to the innermost block whose span contains its first byte (equal spans resolve by parent depth, not text). A match no block contains, which sits where a block's span ends, goes to the innermost block that ends there; the end is inclusive only when no block contains the offset, so a zero-width `$` after a declaration belongs to it. A hit that no match credited goes to the innermost blocks at each byte of its line. A hit goes once to every block credited. (Decided per match, not per hit: `const a = 1; const needle = 2;` searched for `const` has a match in each block, and the line-based rule credited both.)
- The invariant: every matched line with a byte in at least one block credits at least one block, so a block is never dropped for lack of a hit while a match touches it. A line no block touches is a match outside every declaration and has no block to return.
- The sink finds the starts of each pattern on its own and merges them. The searcher's alternation matches left to right without overlap, so one pattern's match (`class.*`) could hide another's (`m`).
- A block carries the span of its declaration's head (`signature_span`), which the signature is the one-line form of. The snippet cuts its lines from the block and leaves out a matched line that lies inside the head.
- Dedup compares spans: a block is dropped when it shares more than half of the smaller span's bytes with a block already kept in the same file. The spans of one analyzed file nest or are disjoint, so that is containment or equality.

## Consequences

Deleted: own-text matching and the equal-range rule in `owned_hits`, `signature_shows`, the head-cutting in `name_match_boost` with its `unrestricted` special case, and the proptest's reference reimplementation.

Costs:

- `LineHit` grows a list of match start offsets. The searcher does not give them: `SinkMatch` in `grep-searcher` 0.1.17 (`sink.rs:379-423`) exposes only `bytes()`, `absolute_byte_offset()` and `line_number()` for the whole line. In-line offsets need `Matcher::find_iter` (`grep-matcher` 0.1.9, `lib.rs:629`) over each matching line. `LineCollector::text_matches` (`text_search.rs`) already makes that second pass for CRLF lines.
- Offsets must mean the same bytes on both sides. The searcher sees raw file bytes and the analyzer sees the lossy-decoded `String`, which differ after any invalid UTF-8.
- Each block gains a span (16 bytes), a parent index (4 to 8 bytes) and a head span (24 bytes with its `Option` tag). `code` stays, so nested blocks keep duplicating text.
- Dedup compares bytes instead of lines, the one stage whose output can change beyond the old bugs.

## Alternatives considered

Keep line ranges and patch each case, as we did. It costs a commit per new line shape, and each patch adds a rule the next must respect.

## Order of work

Three PRs. After each, `scripts/rg-compare.py` must not drop: identifier 58/59, questions 17/18, members 15/16, Rust fd 22/24, held-out 23/24 and 12/12. Output is byte-identical except the cases the old rules got wrong, which each PR lists.

1. Analyzers emit spans, parent indices, `name` and `kind`. Nothing reads them yet. Tests assert spans slice to `code`.
2. The sink reports match ranges and `owned_hits` becomes innermost-containing. Test-first: the three line shapes above and the same-range test function and module.
3. `snippet`, `name_match_boost` and `dedup_blocks` read spans and typed fields.

## Not measured

Memory and time of the second regex pass and the spans on a large repo. How many harness queries change under byte-based dedup (none of 421; decision log 43). Whether mapping lossy offsets beats searching decoded text. How many of the 87 sites would change.
# Language Analyzer Contract — Semantic Model

Source: `docs/spec/01-core-architecture.md` §11 (`analysis/lang.rs`, the `LanguageAnalyzer` trait) and
`docs/spec/03-multi-language-platform.md` §3 (`analysis/registry.rs`, `AnalyzerRegistry`). The code in
`crates/monokl/src/analysis/` is smaller than the spec: it has what `monokl search` reads.

## `LanguageAnalyzer` trait (`analysis/lang.rs`)

```rust
pub trait LanguageAnalyzer: Send + Sync {
    fn languages(&self) -> &[Language];
    fn supports(&self, path: &Utf8Path) -> bool;
    fn analyze(&self, path: &Utf8Path, source: String) -> Result<Arc<FileAnalysis>>;
}
```

- `languages` is a slice because one instance can own several languages (`TsAnalyzer` owns `Language::TypeScript` and
  `Language::JavaScript`). Do not collapse it back to one analyzer per language.
- `supports` asks `Language::of(path)`, so the extensions and the declaration-file exclusion are defined once in
  `analysis/lang.rs`, not per analyzer.
- `analyze` takes the text, not a closure: search has already read the file (and replaced invalid UTF-8) before it asks.
  It returns `blocks`, `test_blocks`, `had_parse_errors` and `degradation`, which is all search reads.
- `Language` has the languages an analyzer exists for: `TypeScript`, `JavaScript` and `Rust`. It is also the `--language` value.

Removed because no command read them: `language_for`, `capabilities`, `AnalyzerCapabilities`, `CapabilityPrecision`,
`analyze_with_profile` and `AnalysisProfile` (`Dependencies` and `Structural` were never requested; search always asked
for `Full`). A command that gates on precision, or needs a cheaper pass, restores the one it uses together with the
analyzer output it reads. The spec's shapes for them (`languages() -> &[Language]`, a per-language
`capabilities(language)`, `language_for(path)`) are the ones to restore, so an analyzer that owns several languages
stays expressible.

## `AnalyzerRegistry` (`analysis/registry.rs`)

```rust
pub struct AnalyzerRegistry { analyzers: Vec<Arc<dyn LanguageAnalyzer>> }

impl AnalyzerRegistry {
    pub fn new(analyzers: Vec<Arc<dyn LanguageAnalyzer>>) -> Self;
    pub fn analyzer_for(&self, path: &Utf8Path) -> Option<&dyn LanguageAnalyzer>;
    pub fn handles(&self, language: Language) -> bool;
}
```

- **First-match-by-registration-order, not specificity**: linear `find`, the first `supports(path)` wins.
- **No match is `None`, with no diagnostic from the registry itself.** The caller decides what to say.
- `Arc<dyn LanguageAnalyzer>` throughout so the registry is shareable across rayon workers.

## Diagnostic-signal gaps — must be resolved, not ported as-is

Open questions for spec@1 (edge-case audit Part 3, findings #6/#10/#14), not resolved designs. Planned: `AnalyzerCapabilities`, `pick_main_struct` and `add_missing_analyzer_diagnostic` are not in the code.

1. **#6 — macro-generated code and inactive `#[cfg(...)]` branches are invisible, zero
   capability/precision signal**, unlike every other Rust precision limitation in the spec. The
   crate-graph heuristic gets a signal (`resolved_import_graph: Structural`); `pick_main_struct`
   — which can arbitrarily pick a platform-dead struct as "the" struct — gets none.
   `AnalyzerCapabilities` has no field for "syntactically present but semantically
   unreachable/unexpanded." Decide: new capability field, or a per-result `Diagnostic` instead of
   a static one. Do not ship `pick_main_struct` silently without picking one.
2. **#10 — the "no analyzer" diagnostic conflates two facts.** `add_missing_analyzer_diagnostic`
   derives its message from `candidate_language(path)`, extension-only (`.ts` → `TypeScript`), and
   doesn't see `TsAnalyzer::supports`'s explicit `.d.ts` exclusion. A `.d.ts` file — TS fully
   supported, this one file intentionally out of scope by design — gets the same
   `"{op} is not supported for TypeScript files in this build"` message a truly-unsupported
   language would get. An agent parsing diagnostics can't tell "no analyzer in this build" from
   "supported language, this file deliberately excluded." Decide: distinguish
   `supports() == false but language recognized`, or add a distinct message template for
   intentional per-file exclusions.
3. **#14 — `Vec<Diagnostic>` has no stated ceiling**, unlike every other result list in the spec
   (symbols: 50/file, 500 total; dependents: 200). Lower priority than #6/#10 — resource-bound
   (pathological workspace → unbounded list), not a correctness/signal gap.

